const input = $input.first().json;
const st = $getWorkflowStaticData('global');
if (!st.cache) st.cache = {};

const keyword = input.keyword;
const config = input.config;
const ttlMs = (config.cache_ttl_minutes || 30) * 60 * 1000;
const now = Date.now();

const cached = st.cache[keyword];

if (cached && (now - cached.ts_epoch_ms < ttlMs)) {
  return [{
    json: {
      keyword,
      config,
      cache_hit: true,
      cached_items: cached.items || [],
      cached_hits: 1,
      api_calls: 0,
      failed_calls: 0
    }
  }];
}

return [{
  json: {
    keyword,
    config,
    cache_hit: false,
    cached_hits: 0,
    api_calls: 0,
    failed_calls: 0
  }
}];

const data = $json;
if (!data.cached_items || data.cached_items.length === 0) {
  return [{ json: { __empty: true, __stream: 'cache' } }];
}
return data.cached_items.map(i => ({
  json: { ...i, meta: { ...i.meta, cached: true, api_calls: 0, failed_calls: 0 } }
}));

const cacheGate = $('Cache Gate').first().json;
const keyword = cacheGate.keyword;
const data = $json;

if (!data || !data.hits || data.error) {
  return [{ json: { __empty: true, __src: 'hn', meta: { failed_calls: 1 } } }];
}

return data.hits.map(h => ({
  json: {
    source: 'hn',
    keyword,
    title: h.title,
    url: h.url || `https://news.ycombinator.com/item?id=${h.objectID}`,
    published_at: h.created_at ? new Date(h.created_at).toISOString() : null,
    raw_score: (h.points || 0) + (h.num_comments || 0),
    score: (h.points || 0) + (h.num_comments || 0),
    summary_raw: null,
    summary: null,
    meta: { author: h.author, venue: 'Hacker News', cached: false, api_calls: 0, failed_calls: 0 }
  }
}));

const cacheGate = $('Cache Gate').first().json;
const keyword = cacheGate.keyword;
const data = $json;

if (!data || !data.query || !data.query.search || data.error) {
  return [{ json: { __empty: true, __src: 'wikipedia', meta: { failed_calls: 1 } } }];
}

return data.query.search.map(hit => ({
  json: {
    source: 'wikipedia',
    keyword,
    title: hit.title,
    url: `https://en.wikipedia.org/wiki/${encodeURIComponent(hit.title.replace(/ /g, '_'))}`,
    published_at: null,
    raw_score: Math.floor((hit.size || 0) / 100),
    score: Math.floor((hit.size || 0) / 100),
    summary_raw: hit.snippet || null,
    summary: null,
    meta: { author: null, venue: 'Wikipedia', cached: false, api_calls: 0, failed_calls: 0 }
  }
}));

const cacheGate = $('Cache Gate').first().json;
const keyword = cacheGate.keyword;
const data = $json;

if (!data || !data.message || !data.message.items || data.error) {
  return [{ json: { __empty: true, __src: 'crossref', meta: { failed_calls: 1 } } }];
}

return data.message.items.map(item => ({
  json: {
    source: 'crossref',
    keyword,
    title: (item.title && item.title[0]) ? item.title[0] : 'Untitled',
    url: item.URL || '',
    published_at: (item['published-print'] && item['published-print']['date-time']) ? item['published-print']['date-time'] : null,
    raw_score: 20 + (item['is-referenced-by-count'] || 0),
    score: 20 + (item['is-referenced-by-count'] || 0),
    summary_raw: null,
    summary: null,
    meta: {
      author: item.author ? item.author[0].family : null,
      venue: item['container-title'] ? item['container-title'][0] : 'Crossref',
      cached: false,
      api_calls: 0,
      failed_calls: 0
    }
  }
}));

const cacheGate = $('Cache Gate').first().json;
const keyword = cacheGate.keyword;
const st = $getWorkflowStaticData('global');
const allItems = $input.all();

// Count failed calls
let failedCalls = 0;
const validItems = allItems
  .map(i => i.json)
  .filter(i => {
    if (i.__empty) {
      if (i.meta?.failed_calls) failedCalls += i.meta.failed_calls;
      else failedCalls++;
      return false;
    }
    return true;
  });

st.cache[keyword] = {
  ts_epoch_ms: Date.now(),
  items: validItems
};

if (validItems.length === 0) {
  return [{ json: { __empty: true, keyword, meta: { cached: false, api_calls: 3, failed_calls: failedCalls || 3 } } }];
}

return validItems.map(item => ({
  json: {
    ...item,
    meta: { ...item.meta, cached: false, api_calls: 3, failed_calls: 0 }
  }
}));
